import { BookOpen, Code, ExternalLink, FileText } from "lucide-react";
import React from "react";
import ReactGA from "react-ga4";

// Base themed components
const ThemedSection = ({ title, icon: Icon, children }) => (
	<section id='publications' className='mb-16'>
		<h2 className='text-3xl font-bold text-gray-800 dark:text-slate-50 mb-6 flex items-center gap-2'>
			<Icon className='w-8 h-8 text-purple-600 dark:text-violet-400' />
			{title}
		</h2>
		{children}
	</section>
);

const BulletPoint = ({ children }) => (
	<li className='text-sm text-gray-600 dark:text-slate-300 flex items-center gap-2'>
		<span className='w-1.5 h-1.5 bg-gradient-to-r from-purple-500 to-indigo-500 dark:from-violet-400 dark:to-fuchsia-400 rounded-full'></span>
		{children}
	</li>
);

const ResourceLink = ({ href, icon: Icon, children, variant = "default" }) => {
	const baseClasses =
		"inline-flex items-center gap-1 px-3 py-1 rounded-full text-sm transition-all duration-300";
	const variants = {
		default:
			"bg-gradient-to-r from-purple-500 to-indigo-500 dark:from-violet-500 dark:to-fuchsia-500 text-white hover:from-purple-600 hover:to-indigo-600 dark:hover:from-violet-600 dark:hover:to-fuchsia-600",
		arxiv:
			"bg-gradient-to-r from-green-500 to-emerald-500 text-white hover:from-green-600 hover:to-emerald-600",
		code: "bg-gradient-to-r from-gray-500 to-slate-500 text-white hover:from-gray-600 hover:to-slate-600",
	};
	const trackResourceClick = () => {
		ReactGA.event({
			category: "Publication",
			action: "resource_click",
			label: `${children} - ${href}`,
		});
	};

	return (
		<a
			href={href}
			target='_blank'
			rel='noopener noreferrer'
			onClick={trackResourceClick}
			className={`${baseClasses} ${variants[variant]}`}
		>
			<Icon className='w-4 h-4' />
			{children}
		</a>
	);
};

const AuthorLink = ({ name, orcid, email }) => {
	const trackEmailClick = () => {
		ReactGA.event({
			category: "Publication",
			action: "author_email_click",
			label: `${name} - ${email}`,
		});
	};

	const trackOrcidClick = () => {
		ReactGA.event({
			category: "Publication",
			action: "orcid_click",
			label: `${name} - ${orcid}`,
		});
	};
	return (
		<span className='inline-flex items-center gap-1'>
			<a
				onClick={trackEmailClick}
				href={`mailto:${email}`}
				className='text-purple-600 dark:text-violet-400 hover:text-purple-800 dark:hover:text-violet-300'
			>
				{name}
			</a>
			{orcid && (
				<a
					href={`https://orcid.org/${orcid}`}
					target='_blank'
					onClick={trackOrcidClick}
					rel='noopener noreferrer'
					className='text-green-600 hover:text-green-800 dark:text-green-400 dark:hover:text-green-300'
				>
					<img
						src='https://orcid.org/assets/vectors/orcid.logo.icon.svg'
						alt='ORCID'
						className='w-4 h-4 inline'
					/>
				</a>
			)}
		</span>
	);
};

const AuthorsList = ({ authors }) => (
	<div className='flex flex-wrap gap-2'>
		{authors.map((author, index) => (
			<React.Fragment key={index}>
				<AuthorLink {...author} />
				{index < authors.length - 1 && (
					<span className='text-gray-400 dark:text-slate-500'>, </span>
				)}
			</React.Fragment>
		))}
	</div>
);

const PublicationCard = ({
	type,
	title,
	authorsList,
	venue,
	year,
	abstract,
	impact,
	links,
}) => {
	const trackPublicationInteraction = (interactionType) => {
		ReactGA.event({
			category: "Publication",
			action: "publication_interaction",
			label: `${interactionType} - ${title}`,
		});
	};
	return (
		<div
			onMouseEnter={() => trackPublicationInteraction("hover")}
			className='bg-gradient-to-br from-purple-50 to-indigo-50 dark:from-slate-800/90 dark:to-slate-900/90 rounded-lg shadow-md dark:shadow-lg dark:shadow-slate-900/50 p-6 hover:shadow-lg transition-all duration-300'
		>
			<div className='flex items-start justify-between'>
				<div>
					<div className='inline-block text-sm font-medium text-purple-600 dark:text-violet-400 bg-purple-100 dark:bg-violet-500/20 px-3 py-1 rounded-full mb-2'>
						{type}
					</div>
					<h3 className='text-xl font-semibold text-gray-800 dark:text-slate-50 mb-2'>
						{title}
					</h3>
					<AuthorsList authors={authorsList} />
					<div className='text-sm font-medium text-purple-600 dark:text-violet-400 bg-purple-50 dark:bg-violet-500/20 px-3 py-1 rounded-full inline-block mt-2'>
						{venue} • {year}
					</div>
				</div>
			</div>

			<div className='mt-4 mb-4'>
				<h4 className='text-sm font-semibold text-gray-700 dark:text-slate-200 mb-2'>
					Abstract
				</h4>
				<p className='text-gray-600 dark:text-slate-300 text-sm'>{abstract}</p>
			</div>

			{impact && (
				<div className='mb-4'>
					<h4 className='text-sm font-semibold text-gray-700 dark:text-slate-200 mb-2'>
						Key Contributions
					</h4>
					<ul className='list-none space-y-1'>
						{impact.map((point, index) => (
							<BulletPoint key={index}>{point}</BulletPoint>
						))}
					</ul>
				</div>
			)}

			{links && (
				<div className='flex flex-wrap gap-2 mt-4 pt-4 border-t border-purple-100 dark:border-violet-500/20'>
					{links.paper && (
						<ResourceLink href={links.paper} icon={FileText}>
							Paper
						</ResourceLink>
					)}
					{links.arxiv && (
						<ResourceLink
							href={links.arxiv}
							icon={ExternalLink}
							variant='arxiv'
						>
							arXiv
						</ResourceLink>
					)}
					{links.code && (
						<ResourceLink href={links.code} icon={Code} variant='code'>
							Code
						</ResourceLink>
					)}
					{links.slides && (
						<ResourceLink href={links.slides} icon={FileText}>
							Slides
						</ResourceLink>
					)}
					{links.preprint && (
						<ResourceLink href={links.preprint} icon={FileText}>
							Preprint
						</ResourceLink>
					)}
					{links.supplementary && (
						<ResourceLink href={links.supplementary} icon={FileText}>
							Supplementary
						</ResourceLink>
					)}
					{links.presentation && (
						<ResourceLink href={links.presentation} icon={FileText}>
							Presentation
						</ResourceLink>
					)}
				</div>
			)}
		</div>
	);
};

