// Base themed components
const ThemedSection = ({ title, icon: Icon, children }) => (
	<section id='teaching' className='mb-16'>
		<h2 className='text-3xl font-bold text-gray-800 dark:text-slate-50 mb-6 flex items-center gap-2'>
			<Icon className='w-8 h-8 text-purple-600 dark:text-violet-400' />
			{title}
		</h2>
		{children}
	</section>
);

const ThemedCard = ({ title, icon: Icon, children }) => (
	<div className='bg-gradient-to-br from-purple-50 to-indigo-50 dark:from-slate-800/90 dark:to-slate-900/90 rounded-lg shadow-md dark:shadow-lg dark:shadow-slate-900/50 p-6 mb-8'>
		<h3 className='text-xl font-semibold text-gray-800 dark:text-slate-50 mb-6 flex items-center gap-2'>
			<div className='p-2 bg-purple-100 dark:bg-violet-500/20 rounded-lg'>
				<Icon className='w-6 h-6 text-purple-600 dark:text-violet-400' />
			</div>
			{title}
		</h3>
		{children}
	</div>
);

const TeachingCard = ({
	icon,
	title,
	institution,
	date,
	description,
	highlights,
	metrics,
	topics,
	images,
	imageDescriptions,
}) => {
	const [open, setOpen] = useState(false);
	const [index, setIndex] = useState(0);

	const slides = images
		? images.map((image, idx) => ({
				src: image,
				alt: imageDescriptions[idx],
				title: title,
				description: imageDescriptions[idx],
		  }))
		: [];

	const handleImageClick = (imageIndex) => {
		// Track individual image clicks
		ReactGA.event({
			category: "Teaching",
			action: "image_click",
			label: `${title} - ${institution} - ${
				imageDescriptions[imageIndex] || `Image ${imageIndex + 1}`
			}`,
		});
		setIndex(imageIndex);
		setOpen(true);
	};

	const handleLightboxClose = () => {
		// Track lightbox closes
		ReactGA.event({
			category: "Teaching",
			action: "lightbox_close",
			label: `${title} - ${institution}`,
		});
		setOpen(false);
	};

	const handleSlideChange = (newIndex) => {
		// Track when users view different images in the lightbox
		ReactGA.event({
			category: "Teaching",
			action: "image_view",
			label: `${title} - ${institution} - ${
				imageDescriptions[newIndex] || `Image ${newIndex + 1}`
			}`,
		});
	};

	// Track when users click topic tags
	const handleTopicClick = (topic) => {
		ReactGA.event({
			category: "Teaching",
			action: "topic_click",
			label: `${title} - ${topic}`,
		});
	};

	const displayImages = images ? images.slice(0, 2) : [];
	const remainingImagesCount = images ? images.length - 2 : 0;

	return (
		<div className='bg-white dark:bg-slate-800/50 rounded-lg shadow-lg overflow-hidden border border-purple-100 dark:border-violet-500/20 hover:shadow-xl transition-all duration-300 backdrop-blur-sm'>
			{/* Header Section */}
			<div className='p-6 bg-gradient-to-br from-purple-50 to-indigo-50 dark:from-slate-800/90 dark:to-slate-900/90'>
				<div className='flex items-center gap-2 mb-2'>
					<div className='p-2 bg-white dark:bg-slate-800/50 rounded-lg shadow-sm border border-transparent dark:border-violet-500/20'>
						{React.cloneElement(icon, {
							className: "w-6 h-6 text-purple-600 dark:text-violet-400",
						})}
					</div>
					<h4 className='text-xl font-semibold text-gray-800 dark:text-slate-50'>
						{title}
					</h4>
				</div>
				<div className='text-gray-600 dark:text-slate-300'>{institution}</div>
				{date && (
					<div className='inline-block text-sm font-medium text-purple-600 dark:text-violet-400 bg-purple-50 dark:bg-violet-500/20 px-3 py-1 rounded-full mt-2'>
						{date}
					</div>
				)}
			</div>

			{/* Images Section with Gallery */}
			{images && images.length > 0 && (
				<div className='mt-6 mb-6'>
					<div className='grid grid-cols-2 gap-4 px-6'>
						{displayImages.map((image, idx) => (
							<div
								key={idx}
								className='relative group cursor-pointer overflow-hidden rounded-lg'
								onClick={() => handleImageClick(idx)}
							>
								<img
									src={image}
									alt={imageDescriptions[idx]}
									className='w-full h-48 object-cover transition-transform duration-300 group-hover:scale-110'
								/>
								{idx === 1 && remainingImagesCount > 0 && (
									<div className='absolute inset-0 bg-black bg-opacity-60 flex flex-col items-center justify-center text-white'>
										<ImageIcon className='w-8 h-8 mb-2' />
										<span className='text-lg font-semibold'>
											+{remainingImagesCount} more
										</span>
									</div>
								)}
								{idx !== 1 && (
									<div className='absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-40 transition-all duration-300 flex items-center justify-center'>
										<div className='text-white text-center opacity-0 group-hover:opacity-100 transition-opacity duration-300 p-4'>
											<p className='text-sm'>{imageDescriptions[idx]}</p>
										</div>
									</div>
								)}
							</div>
						))}
					</div>

					<Lightbox
						open={open}
						close={handleLightboxClose}
						index={index}
						slides={slides}
						plugins={[Thumbnails, Zoom, Slideshow]}
						thumbnails={{
							position: "bottom",
							width: 120,
							height: 80,
						}}
						zoom={{
							maxZoomPixelRatio: 3,
							scrollToZoom: true,
							onZoomChange: (zoom) => {
								ReactGA.event({
									category: "Teaching",
									action: "image_zoom",
									label: `${title} - Zoom Level: ${zoom}`,
								});
							},
						}}
						slideshow={{
							autoplay: true,
							delay: 3000,
						}}
						on={{
							view: ({ index: newIndex }) => handleSlideChange(newIndex),
							click: () => {
								ReactGA.event({
									category: "Teaching",
									action: "lightbox_click",
									label: `${title} - ${institution} - ${
										imageDescriptions[index] || `Image ${index + 1}`
									}`,
								});
							},
						}}
					/>
				</div>
			)}

			<div className='p-6'>
				<p className='text-gray-700 dark:text-slate-300 mb-6'>{description}</p>

				{/* Metrics Grid */}
				{metrics && (
					<div className='grid grid-cols-3 gap-6 mb-6'>
						{metrics.map((metric, index) => (
							<div
								key={index}
								className='bg-gradient-to-br from-purple-50 to-indigo-50 dark:from-slate-800/50 dark:to-slate-900/50 rounded-xl p-4 text-center backdrop-blur-sm'
							>
								<div className='text-2xl font-bold text-purple-600 dark:text-violet-400'>
									{metric.value}
								</div>
								<div className='text-sm text-gray-600 dark:text-slate-300'>
									{metric.label}
								</div>
							</div>
						))}
					</div>
				)}

				{/* Highlights Section */}
				{highlights && (
					<div className='mb-6'>
						<h5 className='font-semibold text-gray-800 dark:text-slate-200 mb-3'>
							Key Highlights
						</h5>
						<div className='space-y-2'>
							{highlights.map((highlight, index) => (
								<div key={index} className='flex items-start gap-2'>
									<span className='w-1.5 h-1.5 bg-gradient-to-r from-purple-500 to-indigo-500 dark:from-violet-400 dark:to-fuchsia-400 rounded-full mt-2'></span>
									<span className='text-gray-600 dark:text-slate-300'>
										{highlight}
									</span>
								</div>
							))}
						</div>
					</div>
				)}

				{/* Topics Tags */}
				{topics && (
					<div className='flex flex-wrap gap-2'>
						{topics.map((topic, index) => (
							<span
								key={index}
								onClick={() => handleTopicClick(topic)}
								className='px-3 py-1 bg-gradient-to-r from-purple-500 to-indigo-500 dark:from-violet-500 dark:to-fuchsia-500 text-white rounded-full text-sm hover:from-purple-600 hover:to-indigo-600 dark:hover:from-violet-600 dark:hover:to-fuchsia-600 transition-all duration-300'
							>
								{topic}
							</span>
						))}
					</div>
				)}
			</div>
		</div>
	);
};

