// Base themed components
const ThemedSection = ({ title, icon: Icon, children }) => (
	<section id='certifications' className='mb-16'>
		<h2 className='text-3xl font-bold text-gray-800 dark:text-slate-50 mb-6 flex items-center gap-2'>
			<Icon className='w-8 h-8 text-purple-600 dark:text-violet-400' />
			{title}
		</h2>
		{children}
	</section>
);

const ThemedCard = ({ title, icon: Icon, children, className }) => (
	<div
		className={`bg-gradient-to-br from-purple-50 to-indigo-50 dark:from-slate-800/90 dark:to-slate-900/90 rounded-lg shadow-md dark:shadow-lg dark:shadow-slate-900/50 p-6 hover:shadow-lg transition-all duration-300 ${
			className || ""
		}`}
	>
		<div className='flex items-center gap-2 mb-4'>
			<div className='p-2 bg-purple-100 dark:bg-violet-500/20 rounded-lg'>
				<Icon className='w-6 h-6 text-purple-600 dark:text-violet-400' />
			</div>
			<h3 className='text-lg font-semibold text-gray-800 dark:text-slate-50'>
				{title}
			</h3>
		</div>
		{children}
	</div>
);

const Tag = ({ children, color = "purple" }) => (
	<span
		className={`text-xs font-medium text-${color}-600 dark:text-violet-400 bg-${color}-50 dark:bg-violet-500/20 px-2 py-1 rounded-full flex items-center gap-1`}
	>
		{children}
	</span>
);

const CertificationCard = ({
	title,
	issuer,
	certId,
	link,
	date,
	imagePath,
	pdfPath,
	issueDate,
	expiryDate,
	logoUrl,
	onClick,
}) => {
	const hasDocument = imagePath || pdfPath;
	const isPdf = pdfPath && pdfPath.toLowerCase().endsWith(".pdf");
	const documentPath = isPdf ? pdfPath : imagePath;

	const handleDocumentView = () => {
		ReactGA.event({
			category: "Certification",
			action: "view_document",
			label: `${title} - ${isPdf ? "PDF" : "Image"}`,
		});
		onClick(documentPath);
	};

	// Track verification link click
	const handleVerifyClick = () => {
		ReactGA.event({
			category: "Certification",
			action: "verify_click",
			label: `${title} - ${certId || "No ID"}`,
		});
	};

	return (
		<div className='bg-white dark:bg-slate-800/50 rounded-lg p-4 hover:shadow-md transition-all duration-300 border border-purple-100 dark:border-violet-500/20 backdrop-blur-sm'>
			<div className='flex justify-between gap-4'>
				<div className='flex-1'>
					<div className='flex items-start gap-3 mb-2'>
						{logoUrl ? (
							<img
								src={logoUrl}
								alt={issuer}
								className='w-8 h-8 object-contain'
							/>
						) : (
							<div className='w-8 h-8 bg-purple-50 dark:bg-violet-500/20 rounded-full flex items-center justify-center'>
								<Award className='w-4 h-4 text-purple-400 dark:text-violet-400' />
							</div>
						)}
						<div>
							<h4 className='font-medium text-gray-800 dark:text-slate-50'>
								{title}
							</h4>
							<p className='text-sm text-gray-600 dark:text-slate-300'>
								{issuer}
							</p>
						</div>
					</div>

					<div className='flex flex-wrap gap-2 mt-2'>
						{certId && (
							<Tag>
								<Key className='w-3 h-3' />
								{certId}
							</Tag>
						)}

						{date && (
							<Tag>
								<Calendar className='w-3 h-3' />
								{date}
							</Tag>
						)}

						{(issueDate || expiryDate) && (
							<Tag>
								<Calendar className='w-3 h-3' />
								{issueDate} - {expiryDate}
							</Tag>
						)}
					</div>

					<div className='flex gap-2 mt-3'>
						{link && (
							<a
								href={link}
								target='_blank'
								rel='noopener noreferrer'
								onClick={handleVerifyClick}
								className='inline-flex items-center gap-2 px-3 py-1 bg-gradient-to-r from-purple-600 to-indigo-600 dark:from-violet-500 dark:to-fuchsia-500 text-white rounded-full text-xs font-medium hover:from-purple-700 hover:to-indigo-700 dark:hover:from-violet-600 dark:hover:to-fuchsia-600 transition-all'
							>
								<ExternalLink className='w-3 h-3' />
								Verify
							</a>
						)}
						{hasDocument && (
							<button
								onClick={handleDocumentView}
								className='inline-flex items-center gap-2 px-3 py-1 bg-purple-50 dark:bg-violet-500/20 text-purple-600 dark:text-violet-400 rounded-full text-xs font-medium hover:bg-purple-100 dark:hover:bg-violet-500/30 transition-colors'
							>
								{isPdf ? (
									<FileText className='w-3 h-3' />
								) : (
									<Eye className='w-3 h-3' />
								)}
								View Full
							</button>
						)}
					</div>
				</div>

				{hasDocument && (
					<div
						className='hidden md:flex flex-shrink-0 w-24 h-16 rounded-lg overflow-hidden border border-purple-100 dark:border-violet-500/20 cursor-pointer hover:border-purple-200 dark:hover:border-violet-500/30 transition-colors'
						onClick={handleDocumentView}
					>
						{isPdf ? (
							<div className='w-full h-full bg-purple-50 dark:bg-violet-500/20 flex items-center justify-center'>
								<FileText className='w-8 h-8 text-purple-400 dark:text-violet-400' />
							</div>
						) : (
							<img
								src={imagePath}
								alt={`${title} certificate`}
								className='w-full h-full object-cover'
							/>
						)}
					</div>
				)}
			</div>
		</div>
	);
};

const DocumentModal = ({ isOpen, onClose, documentPath }) => {
	if (!isOpen) return null;

	const isPdf = documentPath?.toLowerCase().endsWith(".pdf");

	return (
		<div className='fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50'>
			<div
				className={`bg-white dark:bg-slate-800 p-4 rounded-lg ${
					isPdf ? "w-[90vw] max-w-5xl" : "max-w-4xl"
				} max-h-[90vh] overflow-auto border border-purple-100 dark:border-violet-500/20`}
			>
				{isPdf ? (
					<div className='w-full h-[80vh]'>
						<iframe
							src={`${documentPath}#view=FitH`}
							className='w-full h-full'
							title='Certificate PDF'
						/>
					</div>
				) : (
					<img
						src={documentPath}
						alt='Certificate'
						className='max-w-full h-auto'
					/>
				)}
				<button
					onClick={onClose}
					className='mt-4 px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 dark:from-violet-500 dark:to-fuchsia-500 text-white rounded-lg hover:from-purple-700 hover:to-indigo-700 dark:hover:from-violet-600 dark:hover:to-fuchsia-600 transition-all'
				>
					Close
				</button>
			</div>
		</div>
	);
};

